CREATE TABLE announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,title text NOT NULL,body text NOT NULL,published boolean NOT NULL DEFAULT false,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id));
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,name text NOT NULL,serial_number text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id),UNIQUE(id,organization_id));
CREATE TABLE maintenance_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,asset_id uuid NOT NULL,title text NOT NULL,due_on date NOT NULL,completed_at timestamptz,completed_by uuid REFERENCES users(id),report text NOT NULL DEFAULT '',FOREIGN KEY(asset_id,organization_id) REFERENCES assets(id,organization_id));
CREATE TABLE meters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,serial_number text NOT NULL,kind text NOT NULL CHECK(kind IN ('water','electricity','gas')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),UNIQUE(organization_id,serial_number));
CREATE TABLE meter_readings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),meter_id uuid NOT NULL REFERENCES meters(id),value_thousandths bigint NOT NULL CHECK(value_thousandths>=0),period date NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(meter_id,period));
CREATE TABLE meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES users(id),CHECK(ends_at>starts_at),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id));
CREATE TABLE agenda_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),meeting_id uuid NOT NULL REFERENCES meetings(id),title text NOT NULL);
CREATE TABLE votes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agenda_item_id uuid NOT NULL REFERENCES agenda_items(id),unit_id uuid NOT NULL REFERENCES units(id),voter_id uuid NOT NULL REFERENCES users(id),choice text NOT NULL CHECK(choice IN ('yes','no','abstain')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(agenda_item_id,unit_id));
CREATE TABLE expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,description text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),created_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),approved_at timestamptz,CHECK(approved_by IS NULL OR approved_by<>created_by),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id));
CREATE TABLE budgets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,period date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id),UNIQUE(building_id,period,currency));
CREATE TABLE import_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES users(id),rows jsonb NOT NULL,errors jsonb NOT NULL,status text NOT NULL CHECK(status IN ('invalid','preview','committed')),created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz,FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),organization_id uuid NOT NULL REFERENCES organizations(id),kind text NOT NULL,entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION notify_request_transition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO notifications(user_id,organization_id,kind,entity_id) SELECT r.author_user_id,r.organization_id,'request.'||NEW.action,NEW.request_id FROM resident_requests r WHERE r.id=NEW.request_id AND r.author_user_id<>NEW.actor_id; RETURN NEW; END $$;
CREATE TRIGGER request_notifications AFTER INSERT ON request_history FOR EACH ROW EXECUTE FUNCTION notify_request_transition();
INSERT INTO permissions(key) VALUES('announcements.manage'),('assets.read'),('assets.manage'),('meters.own'),('meters.manage'),('meetings.read'),('meetings.manage'),('meetings.vote'),('expenses.read'),('expenses.manage'),('expenses.approve'),('imports.manage'),('reports.export') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_key,permission_key) VALUES
('manager','announcements.manage'),('manager','assets.read'),('manager','assets.manage'),('manager','meters.manage'),('manager','meetings.read'),('manager','meetings.manage'),('manager','expenses.read'),('manager','expenses.manage'),('manager','reports.export'),
('accountant','expenses.read'),('accountant','expenses.manage'),('accountant','reports.export'),
('portfolio_owner','expenses.read'),('portfolio_owner','expenses.approve'),('portfolio_owner','reports.export'),
('org_admin','imports.manage'),('unit_owner','meters.own'),('renter','meters.own'),('unit_owner','meetings.read'),('unit_owner','meetings.vote') ON CONFLICT DO NOTHING;
INSERT INTO module_entitlements(organization_id,module) SELECT o.id,m.module FROM organizations o CROSS JOIN (VALUES('community'),('maintenance'),('meters')) m(module) ON CONFLICT DO NOTHING;
